"""Resolve a logical training record to its backing file."""
import json
from pathlib import Path


def resolve(root, record):
    base = Path(root)
    wanted = record.get('sha256')
    tables = [base.joinpath('catalog.json'), base.joinpath('manifest.json')]
    for table in tables:
        if table.is_file():
            for row in json.loads(table.read_text())['rows']:
                if row.get('sha256') == wanted:
                    name = row.get('path')
                    if name and base.joinpath(name).is_file():
                        return name
    raise FileNotFoundError('No backing file located for the requested content hash')
